	CENSUS_STATS_HERE = "(du bist hier)",
	CENSUS_STATS_HIGHEST = "Höchste",
	CENSUS_STATS_HOURS_AGO = "vor %d Std.",
	CENSUS_STATS_HOW = "Wie der Zensus funktioniert",
	CENSUS_STATS_HOW_BUILT = "Wie der Zensus entsteht",
	CENSUS_STATS_HOW_BUILT_BASE = "Der Zensus ist der neueste Datensatz jeder Gilde über dem, was vorher bekannt war. Jede Meldung und jede Weitergabe behält die Zeit, zu der sie beobachtet wurde (die Uhr des Servers, wo das Spiel sie liefert).",
	CENSUS_STATS_HOW_BUILT_NEWER = "Eine neuere Meldung ersetzt die ältere, Gilde für Gilde, außer die anderen Absender der Gilde überstimmen sie, solange die ältere jünger als %d Minuten ist. Die Weitergabe eines Verwahrers behält die Zeit, zu der ihr Datensatz zuerst beobachtet wurde, und ersetzt nie einen danach beobachteten Datensatz; das Weitergeben macht einen Datensatz also nie neuer.",
	CENSUS_STATS_HOW_ESTIMATES = "Schätzungen",
	CENSUS_STATS_HOW_ESTIMATES_GRAPHS = "Die Diagramme sind die eigenen Messpunkte dieses Clients: einer alle %d Minuten, während du spielst (%d Stunden aufbewahrt), und der Höchstwert jedes Tages (%d Tage aufbewahrt).",
	CENSUS_STATS_HOW_ESTIMATES_ONLINE = "Online zählt nur Meldungen der letzten %d Minuten. Eine Gilde behält ihre letzte Größe noch %d Stunden nach ihrer letzten Meldung.",
	CENSUS_STATS_HOW_ESTIMATES_PLAIN = "Personen sind die Charaktere minus die hier bekannten bestätigten verknüpften Twinks: Ein Twink, den niemand verknüpft hat oder dessen zwei Bestätigungen diesen Client noch nicht erreicht haben, zählt als eine Person mehr; die Zahl kann also hoch sein und sinken, wenn Bestätigungen eintreffen.",
	CENSUS_STATS_HOW_ESTIMATES_RATE = "Auf dem Client eines Moderationsteams mit mindestens %d validierten BattleTags sind die Personen eine Schätzung (~): die validierten Accounts plus die noch nicht validierten Charaktere, hochgerechnet mit deren Charakteren pro Account.",
	CENSUS_STATS_HOW_ESTIMATES_ROUND = "Diese Schätzung wird auf drei signifikante Stellen gerundet und fällt nie unter die Spieler, die die Stichproben zählen, und steigt nie über die einfache Zählung.",
	CENSUS_STATS_HOW_SANITIZED = "Bereinigte Daten",
	CENSUS_STATS_HOW_SANITIZED_HELD = "Eine Größe, die weiter gesprungen ist, als sich eine Gilde ändern kann, wird auf ihrer letzten guten Größe gehalten, bis sie bestätigt wird oder in Reichweite kommt (S5).",
	CENSUS_STATS_HOW_SANITIZED_OUT = "Der bereinigte Zensus lässt Gilden aus, die die Moderatoren vom Netz genommen haben (gebannt), und Gilden, von denen seit %d Stunden nichts gehört wurde (verschwunden), und listet beide gesondert auf.",
	CENSUS_STATS_HOW_SANITIZING = "Wie die Bereinigung funktioniert",
	CENSUS_STATS_HOW_SANITIZING_RULES = "Die Bereinigung läuft als nummerierte Regeln: S1 am Eingang, die anderen auf dem, was dieser Client aufbewahrt. Nach dem Eingang ändert keine Regel, was eine Gilde gemeldet hat: Jede lässt einen Wert aus einer Summe heraus, hält ihn auf seinem letzten guten Wert fest oder markiert ihn und vermerkt, warum.",
	CENSUS_STATS_HOW_SANITIZING_S1 = "S1 Gültiger Datensatz: Eine Meldung muss lesbar sein, eine Olympus-Gilde nennen, eine Größe von höchstens %s haben (die Obergrenze des Spiels) und nach Zone, Klasse oder Stufe nicht mehr Spieler zählen, als sie online hat; eine Online-Zahl über ihrer Größe wird auf ihre Größe gekürzt. Eine von einem Verwahrer weitergegebene Zeile darf außerdem nicht mehr Spieler online als Mitglieder haben und nicht mehr als 5 Minuten in die Zukunft datiert sein. Was durchfällt, wird am Eingang abgewiesen: Es kommt nie in den Zensus.",
	CENSUS_STATS_HOW_SANITIZING_S2 = "S2 Aktualität: Online zählt nur Meldungen der letzten %d Minuten: Eine ältere Meldung ist veraltet und fällt aus \"jetzt\" heraus. Eine Gilde behält ihre letzte Größe noch %d Stunden nach ihrer letzten Meldung; danach gilt sie als verschwunden: Sie fällt aus jeder Summe heraus und wird gesondert gelistet. Sie wird %d Tage nach ihrer letzten Meldung vergessen.",
	CENSUS_STATS_HOW_SANITIZING_S3 = "S3 Ausschlüsse: Gilden, die die Moderatoren vom Netz genommen haben (gebannt), sind in keiner Summe, und ihre neuen Meldungen werden abgewiesen; sie werden gesondert gelistet, mit ihrer letzten Größe, wenn dieser Client eine hat. Gilden, die nur mit /who gesehen wurden (dieser Client hat keine Meldung und keine Weitergabe von ihnen), sind ebenfalls in keiner Summe; sie werden gesondert gelistet, mit den Spielern, die /who online gesehen hat.",
	CENSUS_STATS_HOW_SANITIZING_S4 = "S4 Übereinstimmung: Eine Größe aus der Gildenliste deiner eigenen Gilde ist bestätigt. Die Größe jeder anderen Gilde ist, solange ihre letzte Meldung jünger als %d Minuten ist, bestätigt, wenn ein vertrauenswürdiger Verwahrer sie weitergibt oder wenn zwei oder mehr Absender in den letzten %d Minuten über die Gilde abgestimmt haben und kein Streitfall markiert ist (Wie die Validierung funktioniert); einzeln, wenn nur einer abgestimmt hat, und umstritten, wenn ein Streitfall markiert ist; ist sie älter, ist sie veraltet. Alle zählen; jede Gilde trägt ihren Vertrauensgrad.",
	CENSUS_STATS_HOW_SANITIZING_S5 = "S5 Unmöglicher Sprung: Eine Größe, die mehr als %d Mitglieder oder %d%% von der letzten guten Größe der Gilde entfernt ist (je nachdem, was größer ist, plus %d pro Minute seit dieser Größe) und nicht bestätigt ist (einzeln, umstritten oder veraltet: S4), ist weiter, als sich eine Gilde bewegen kann. Sie wird auf der letzten guten Größe gehalten, bis sie bestätigt wird, bis die seitdem vergangenen Minuten sie in Reichweite bringen oder bis dieselbe Größe eine Stunde lang besteht.",
	CENSUS_STATS_HOW_SOURCE = "Woher die Zahlen kommen",
	CENSUS_STATS_HOW_SOURCE_KEPT = "Das Addon jedes Spielers bewahrt diese Meldungen auf: Der Zensus ist die neueste Meldung jeder Gilde. Nichts kommt direkt von den Servern von Blizzard.",
	CENSUS_STATS_HOW_SOURCE_REPORT = "In jeder Olympus-Gilde liest das Addon eines Mitglieds die Gildenliste und meldet ihre Größe alle paar Minuten im Olympus-Kanal; das Addon eines zweiten Mitglieds, wenn eines online ist, meldet sie seltener.",
	CENSUS_STATS_HOW_VALIDATED = "Validierte Daten",
	CENSUS_STATS_HOW_VALIDATED_WHEN = "Die Größe einer Gilde ist bestätigt, wenn sie aus der Gildenliste deiner eigenen Gilde stammt oder, solange ihre letzte Meldung jünger als %d Minuten ist, wenn zwei oder mehr aktuelle Absender ohne Streitfall über die Gilde abgestimmt haben (S4) oder ein vertrauenswürdiger Verwahrer (Verwahrer der Kirche, der König, der Hohe Rat) sie weitergibt.",
	CENSUS_STATS_HOW_VALIDATION = "Wie die Validierung funktioniert",
