	CONSENT_CHAT_TEXT = "[Olympus], [Hauptleute] und [Lords] (/ol, /olc, /oll) und die angeheftete Zeile. Ja: die Zeilen anderer Spieler erscheinen hier, und du kannst schreiben; jede Zeile, die du schreibst, erreicht jeden im Olympus-Kanal. Nein: dieser Client sendet und zeigt sie nicht. (/oly chat on|off)",
	CONSENT_COMPANION = "Pakt für Olympus Companion",
	CONSENT_COMPANION_TEXT = "Nur solange die private Olympus Companion Bridge installiert ist. Ja: bei /reload oder beim Ausloggen darf sie den Namen dieses Charakters, deinen eigenen BattleTag, deine aktuelle Olympus-Gilde, deine tatsächlichen Rollen und Reiter speichern, dazu die Olympus-Chatzeilen anderer Spieler, die dieser Client angenommen hat. Der Companion darf sie an das Olympus-Relay senden, für die Account-Verknüpfung, die Prüfung durch das Team und um einen OLY-Verknüpfungscode zu bezeugen. Dein BattleTag ist nur für das Team sichtbar, nie öffentlich und nie maßgeblich für die Mitgliedschaft. Nein: sie exportiert keine benannte Identität und keinen BattleTag und zeichnet keinen Chat auf; der anonyme Zensus-Kontrollpunkt funktioniert weiterhin.",
	CONSENT_DONE = "Fertig",
	CONSENT_FOOTER = "Das Fenster, der Zensus und die Mitgliederliste deiner eigenen Gilde funktionieren, egal was du antwortest. Ändere jede Antwort später: /oly privacy öffnet diese Seite erneut.",
	CONSENT_GAMES_RECORDED = "Spielergebnisse werden erfasst: jedes Spiel, das du spielst (Knochenwurf, die Arena, das Üben der Lotterie: wann, wer, das Ergebnis und der Punktestand), erscheint in deiner eigenen Liste und geht an den König, den Hohen Rat und den Autor (und die Prüfer, die er signiert), sonst niemanden.",
	CONSENT_INSPECTION = "Die Königliche Inspektion",
	CONSENT_INSPECTION_TEXT = "Wenn der König, sein Truchsess oder eine Hand eine ausruft und dein Addon in der Stichprobe ist, inspiziert es die Olympus-Spieler um dich herum 2 Minuten lang und flüstert dann nur dem, der sie ausgerufen hat: deine Gilde, wie viele den Gildenwappenrock trugen, einen anderen oder keinen, und bis zu 6 Namen von Spielern, die ohne die Farben erwischt wurden. Die Schlachtzugswarnung bekommst du so oder so. (/oly inspection on|off)",
	CONSENT_INTRO = "Unter dem Olympus-Pakt, den du angenommen hast, gehen immer drei Dinge hinaus, solange du in einer Olympus-Gilde bist. Ein Mitglied deiner Gilde, von den Addons gewählt, sendet den Zensus deiner Gilde im Olympus-Kanal: ihre Größe, die Zahl der Spieler online, Klassen, Stufen und Rangnamen, ihren Anführer und ihre Offiziere (Name, online, Tage abwesend, Klasse, Stufe) und ihre fünf Mitglieder mit der höchsten Stufe (Name, Stufe, Klasse), online oder nicht. Und dein Addon grüßt deine Gilde: seine Version, dein Realm, ob dein Kanal öffentlich oder versiegelt ist und ob du deine Zone teilst. Und im Spiel geht dein BattleTag privat nur an das Moderationsteam (/oly accord). Wenn du die App Olympus Companion nutzt, sendet sie jede Olympus- und Gildenchatzeile, die dein Client empfängt, einschließlich deiner eigenen und lokal verborgener Zeilen, an das Team von Olympus, das sie aufbewahrt, um zu bestätigen, was gesagt wurde, und um zu moderieren. %s",
	CONSENT_KEEP_CURRENT = "Aktuelle Auswahl behalten",
	CONSENT_LAYERHELP = "Anderen helfen, deinem Layer beizutreten",
	CONSENT_LAYERHELP_TEXT = "Wenn jemand nach dem Layer fragt, auf dem du bist, darf dein Addon nur ihm zuflüstern, dass du dort bist, und fragt dich dann, ob du ihn einladen willst (du klickst Einladen). Wenn er den Layer des Königs ermittelt, während dessen Krone sichtbar ist, darf eine genaue Sichtung über die Namensplakette nur diesem aktiven Fragenden antworten; zwei unabhängige Beobachter müssen übereinstimmen. Nichts wird gesendet, nur weil du ihn siehst. (/oly layerhelp on|off)",
	CONSENT_LOCATION = "Deine Zone und dein Layer",
	CONSENT_LOCATION_TEXT = "Deine Zone, dein Layer, dein Gildenrang und deine Gilde, mit deinem Namen, an jeden im Olympus-Kanal (Offiziere und eins von acht Mitgliedern geben sie bekannt, alle 10 Minuten und wenn der Layer wechselt), und die Mitglieder deiner Gilde pro Zone in ihrem Zensus. Layerwechsel funktionieren besser, je mehr Mitglieder teilen. (/oly location on|off)",
	CONSENT_NEEDS_LOCATION = "Nur, solange du deine Zone und deinen Layer teilst.",
	CONSENT_NO = "Nein",
	CONSENT_OPTIONAL = "Nichts von dem Folgenden geht hinaus oder erscheint, bevor du Ja sagst, und bis du antwortest, bleibt jedes aus, außer seine Zeile sagt, dass ein früher gegebenes Ja weiter gilt.",
	CONSENT_PATROLSHARE = "Die Funde deiner Patrouillen (Offiziere)",
	CONSENT_PATROLSHARE_TEXT = "Name und Gilde jedes Spielers, den deine eigenen Inspektionen ohne die Farben oder mit einem anderen Wappenrock erwischen (oder wieder mit unserem), an die Offiziere deiner Gilde über Gilden-Addon-Nachrichten, höchstens einmal pro Minute; ihre erscheinen unter Wappenröcke in deiner Wache. Dafür wird nichts mehr oder früher inspiziert, und nichts geht über den Olympus-Kanal. (/oly patrolshare on|off)",
	CONSENT_PRIVATE_PRESENCE = "Private Präsenz",
	CONSENT_PRIVATE_PRESENCE_TEXT = "Für den König, den signierten Hohen Rat und den Autor des Addons. Sie bleibt über Logins hinweg an, bis du sie ausschaltest. Olympus zieht zuerst deinen geteilten Standort zurück und hört dann auf, dich als online anzukündigen oder zu sagen, wo du bist: kein Hallo, keine Zensusmeldung, kein Layer, kein Kartenpunkt und kein anderes Präsenzwort. Nur deine Gilde wird informiert, sodass die Olympus-Clients ihrer Mitglieder dich in dem Zensus, den sie senden, als offline zählen und andere Gilden dich nicht online sehen (Gildenkameraden mit einem älteren Olympus zählen dich womöglich noch). Die Blizzard-Gildenliste deiner Gilde, /who und die Chatzeilen, die du tippst, zeigen dich weiterhin. Das Ausschalten schaltet das Teilen des Standorts nicht wieder ein.",
	CONSENT_PROFILE_IDENTITY = "Profil: Zensus-Identität",
	CONSENT_PROFILE_IDENTITY_TEXT = "Name, Gilde, Rang, Stufe, Klasse und Online-Status stammen aus Fakten, die schon im Zensus, in der Mitgliederliste, in /who oder in diesem Client vorliegen. Ein Profil zu öffnen fragt nichts Neues an.",
	CONSENT_PROFILE_INTRO = "Dieser Abschnitt trennt Fakten, die auf diesem Client gespeichert sind, Fakten, die von anderen Addons empfangen wurden, hier abgeleitete Fakten und Fakten, die du teilen wolltest. Er macht aus nicht verfügbaren Daten keine Vermutung.",
	CONSENT_PROFILE_OPTIONAL = "Nur Zeilen mit Ja und Nein haben einen echten Freigabeschalter. Reine Statuszeilen beschreiben, was das Addon tatsächlich kann; sie können kein Protokoll erlauben, das es nicht gibt.",
	CONSENT_PROFILE_PRESENTATION = "Profil: Arena-Auftritt",
	CONSENT_PROFILE_PRESENTATION_TEXT = "Dein gewählter Arenarahmen, Titel, Spitzname, Emblem und deine kurze Geschichte sind Darstellung, die auf diesem Client gespeichert ist. Das Arena-Begleitaddon ist optional; das normale Profil lädt es nicht.",
	CONSENT_PROFILE_SECTION = "Profil",
	CONSENT_PROFILE_TITLE = "Olympus: Privatsphäre des Profils",
	CONSENT_ROLLCALL = "Der Appell des Autors",
	CONSENT_ROLLCALL_TEXT = "Wenn der Autor des Addons fragt, flüstert dein Addon nur ihm seine Version, den Spielclient und ob es dem Kanal beigetreten ist, der Melder deiner Gilde ist und den Kanal versiegelt hat. Nichts über deinen Charakter. Seine Update-Hinweise erscheinen, außer du sagst Nein. (/oly rollcall on|off)",
	CONSENT_STATE_DERIVED = "Hier abgeleitet",
	CONSENT_STATE_HIDDEN = "Verborgen",
	CONSENT_STATE_LOCAL = "Nur lokal",
	CONSENT_STATE_NO = "Nein",
	CONSENT_STATE_NONE = "Nicht beantwortet: aus",
	CONSENT_STATE_SHARED = "Geteilt",
	CONSENT_STATE_UNAVAILABLE = "Nicht verfügbar",
	CONSENT_STATE_UNKNOWN = "Unbekannt",
	CONSENT_STATE_YES = "Ja",
	CONSENT_TABARD_NEARBY_V2 = "Direkte Wappenrock-Beobachtungen in der Nähe",
	CONSENT_TABARD_NEARBY_V2_TEXT = "Nur nach einer Inspektion, die dein Client bereits abgeschlossen hat, darf er dem genauen Client des Königs flüstern, der sich in den letzten 10 Minuten authentifiziert hat: Name, Olympus-Gilde, Stufe und Wappenrock-Ergebnis dieses Spielers, dazu deine vom Server gestempelte Identität als Beobachter. Der Client des Königs verzeichnet, wann es angekommen ist. Dein Client startet nie eine zweite Inspektion, leitet nie den Bericht eines anderen Spielers weiter und sendet nie den Namen einer betroffenen Person an Gilden- oder Olympus-Kanäle. Höchstens ein Ergebnis für denselben Spieler pro Minute; Rohdaten werden bis zu 24 Stunden aufbewahrt. Nein bricht jeden wartenden Bericht vor der Zustellung ab. Ein neuer Datenvertrag fragt erneut.",
	CONSENT_TABARD_SELF_V2 = "Dein eigener Wappenrock-Bericht",
	CONSENT_TABARD_SELF_V2_TEXT = "Deine vom Server gestempelte Charakteridentität, Olympus-Gilde, Stufe und dein aktuelles Wappenrock-Ergebnis (Gildenwappenrock, ein anderer, keiner, unter Stufe 15 befreit oder unvollständig) werden nur dem genauen Client des Königs zugeflüstert, der sich in den letzten 10 Minuten authentifiziert hat. Höchstens alle 10 Minuten und wenn sich dein Wappenrock ändert. Rohdaten werden bis zu 24 Stunden aufbewahrt. Nein lässt es aus; ein Wechsel zu Nein bricht jeden wartenden Bericht vor der Zustellung ab. Ein neuer Datenvertrag fragt erneut.",
	CONSENT_TITLE = "Olympus: was dieses Addon teilt",
	CONSENT_TREASURER = "Dein Kassenbuch der Schatzkammer (Hüter)",
	CONSENT_TREASURER_EARLY = "Als Schatzmeister sendet dein Ja auch die Namen aller, die vor 1.0 gespendet haben (die frühen Unterstützer, aus dem Kassenbuch von 0.9): jeder Client im Olympus-Kanal empfängt sie, auch die Namen.",
	CONSENT_TREASURER_OLD_YES = "Dein Ja aus 0.9.3 sendet dein Kassenbuch weiter, bis du hier antwortest.",
	CONSENT_TREASURER_TEXT = "Dein Kassenbuch (sein Kontostand, das gespendete Gold und die Gegenstände und wer sie gegeben hat, die Rangliste der Spender) und die Gildenbank von <Olympus>, an jeden im Olympus-Kanal, alle 5 Minuten, während du spielst. Das Addon zeigt sie dem König und seinem Truchsess, und der Armee nur mit den Schaltern des Königs. (/oly treasurer on|off)",
	CONSENT_WANTED_SIGHTINGS = "Meistgesucht-Sichtungen (aus, bis du Ja sagst)",
	CONSENT_WANTED_SIGHTINGS_TEXT = "Wenn dein Client einen Spieler der Horde sieht, der auf deiner Meistgesucht-Liste steht (eine Namensplakette, dein Ziel, die Maus), notiert er seinen Namen und seine GUID, wie das Spiel sie zeigt, deine eigene Kartenposition (gerundet) und deinen Layer in diesem Moment, die Uhrzeit, deinen Namen und deine Gilde. Das erscheint 15 Minuten lang auf deiner eigenen Karte. Es wird auch einem Prüfer zugeflüstert: dem, den du mit Sichtungen an auf der Meistgesucht-Seite wählst (der König, ein Mitglied des Hohen Rats oder der Autor), solange er online ist und Sichtungen annimmt, höchstens drei pro Minute; bis du einen wählst, bekommt es niemand. Er bekommt eine Markierung, wo du standest, beschriftet mit in der Nähe gesehen, mit deinem Namen, für 15 Minuten. Nichts geht hinaus, solange du deine Zone und deinen Layer privat hältst, und an den König nur, solange seine Krone auf der Karte erscheint. Nie jemand, der nicht auf der Liste steht, nie im Olympus-Kanal, nie in einer Instanz. Nichts wird gespeichert außer der Zeit, zu der dein Client jeden zuletzt gesehen hat, auf deiner eigenen Meistgesucht-Liste (nie wo, nie gesendet). Aus, bis du in dieser Zeile Ja sagst oder Alle erlauben wählst, solange sie offen ist: Nein stoppt es sofort, vergisst diese Zeiten, verwirft, was noch nicht gesendet wurde, und bittet den Client des Prüfers, deine Markierungen von seiner Karte zu nehmen; was ihn erreicht hat, bevor du dich ausgeloggt hast, bleibt dort, bis seine 15 Minuten um sind. (/oly sightings on|off)",
	CONSENT_YES = "Ja",
	COPY_BTN = "Kopieren",
