	COURT_TITLE = "Hof halten",
	COURT_WAITING = "Warten auf eine Audienz (%d)",
	COVER_BAD = "Dieser Name kann nicht verwendet werden: ein Vorname und ein Nachname, nur Buchstaben, je 2 bis 12 Buchstaben.",
	COVER_CONSENT_LABEL = "Schutz der Moderatoren: Decknamen",
	COVER_CONSENT_TEXT = "Um bestimmte Moderationsteams zu schützen, hat Olympus Funktionen, die verhindern, dass du die Namen dieser Moderatoren und anderer Personen siehst, während du das Addon nutzt. Mit deinem Ja zeigt dieser Client überall, wo Olympus es kann, den Decknamen eines Moderators anstelle des echten: im Zielfenster, auf Namensplaketten, im Tooltip des Spielers und auf den eigenen Seiten von Olympus, ohne seine Olympus-Zeichen. Mit deinem Ja akzeptierst du, dass du Teil dieser Schutzregelung bist und dass bestimmte Moderatoren sie in gutem Glauben nutzen dürfen. Wenn jemand unter einem Decknamen in böser Absicht handelt, melde es, und es wird schnell geklärt. Nur dieses Addon macht das, nur für dich: die Gildenliste des Spiels, /who und der Chat behalten die echten Namen, und wenn du Olympus ausschaltest, erscheinen sie wieder. Den Namen, den das Spiel in der Welt über einem Charakter zeichnet, kann ein Addon nicht ändern: mit eingeschalteten freundlichen Namensplaketten tritt die Namensplakette (mit dem Decknamen) an seine Stelle.",
	COVER_OFF = "Anonymität aus: dein eigener Name erscheint wieder und du bist zurück im Olympus-Netz.",
	COVER_OFF_BTN = "Ausschalten",
	COVER_ON = "Anonymität angenommen: wer den Schutz der Moderatoren akzeptiert hat, sieht dich als %s. Du bist raus aus Zensus, Positionen, Layern und Sichtungen des Olympus-Netzes. /oly cover off, um zurückzukommen.",
	COVER_ONLY = "Nur der König, der Hohe Rat und der Autor des Addons können Anonymität annehmen.",
	COVER_ON_BTN = "Annehmen",
	COVER_PROMPT = "Anonymität annehmen\n\nWähle den Namen, den die anderen statt deines Namens sehen (ein Vorname und ein Nachname, nur Buchstaben). Wer den Schutz der Moderatoren akzeptiert hat, sieht ihn in deinem Zielfenster, auf deiner Namensplakette, in deinem Tooltip und auf den Seiten von Olympus. Außerdem verlässt du das Olympus-Netz: kein Zensus, keine Position, kein Layer und keine Sichtung von dir geht raus. Deine Moderationsarbeit geht weiterhin raus.",
	COVER_PROMPT_ON = "Anonymität annehmen\n\nDu erscheinst als %s. Ändere den Namen oder schalte sie aus.",
	COVER_STATUS_OFF = "Anonymität ist aus.",
	COVER_STATUS_ON = "Du erscheinst als %s (seit %s).",
	COVER_TAKEN = "Dieser Name kann nicht verwendet werden: er gehört einem echten Spieler oder einem anderen Moderator.",
	COVER_TITLE = "Anonymität annehmen",
	CRAFTER_ABOUT = "Veröffentliche eine Herstellungsanfrage auf der Tafel oder sieh dir die Spieler an, die einen Beruf eingetragen haben (ihr Ja, einmal, wenn sie ihn öffnen). Eine Anfrage hat einen privaten Chat, ausdrückliche Bedingungen und eine bestätigte Lieferung; ein Berufstreffer ist nur ein Hinweis, dass jemand es herstellen kann.",
	CRAFTER_ASK = "Fragen, wer einen Gegenstand herstellen kann...",
	CRAFTER_ASKED = "Gefragt, wer %s herstellen kann: eingetragene Handwerker, die es herstellen können, antworten im Reiter Handwerker.",
