	CRAFTER_ASK_MANY = "Das sind viele Anfragen für 10 Minuten: warte ein wenig.",
	CRAFTER_ASK_PROMPT = "Wer kann es herstellen? Tippe einen Teil des Gegenstandsnamens.",
	CRAFTER_ASK_TIP = "Öffnet die Anfrageseite: suche einen Gegenstand oder füge seinen Link ein, wähle die Menge und die Details und veröffentliche die Anfrage dann auf der Tafel.",
	CRAFTER_ASK_WAIT = "Eine Anfrage alle 15 Sekunden: warte %d Sek.",
	CRAFTER_CAN_MAKE = "Wer %s herstellen kann",
	CRAFTER_EMPTY = "Noch niemand eingetragen: Spieler tragen einen Beruf ein, wenn sie ihn öffnen.",
	CRAFTER_HOW_LIST = "Öffne einen deiner Berufe, um ihn auf der Tafel einzutragen.",
	CRAFTER_ITEM_N = "Gegenstand %d",
	CRAFTER_LINK = "Handwerker: wer es herstellen kann",
	CRAFTER_LINK_TIP = "Die Tafel für Herstellungsanfragen und die Olympus-Spieler, die einen Beruf eingetragen haben: bitte um einen Gegenstand, sieh, wer ihn herstellen kann, und einigt euch privat. Olympus stellt nie her, bietet nie und drückt nie eine geschützte Spielaktion für dich.",
	CRAFTER_LISTED = "Auf der Olympus-Handwerkertafel eingetragen. /oly crafter off trägt dich aus.",
	CRAFTER_LIST_ASK = "%s auf der Olympus-Handwerkertafel eintragen? Dein Name, deine Gilde, dieser Beruf und seine Fertigkeit gehen an jeden Olympus-Spieler deines Realms und deiner Fraktion; dein Addon beantwortet aus den Rezepten, die du kennst, wer einen Gegenstand herstellen kann (ihre IDs, per Flüstern an den, der gefragt hat). Andere flüstern dich an: du stellst für niemanden etwas her, außer du willst es.",
	CRAFTER_LIST_BUSY = "Sein Addon sendet gerade anderen Spielern seine Rezepte: klicke in einer Minute erneut.",
