	LETTER_SIGNED = "Der Olympus-Entwickler",
	LETTER_TITLE = "Olympus %s",
	LEVEL_N = "Stufe %d",
	LEVEL_RACE = "Stufenrennen",
	LOCATION_ASK = "|cffe6c35cOlympus: deine Zone und deinen Layer teilen?|r\n\nWenn du teilst, kann das Addon im Olympus-Kanal deine Zone, deinen Layer, deinen Gildenrang und deine Gilde bekanntgeben, mit deinem Namen auf jeder Nachricht (das Spiel fügt ihn hinzu): Offiziere und eines von acht Mitgliedern tun das, alle 10 Minuten und wenn sich ihr Layer ändert. Der Zensus deiner Gilde nennt dann deine Zone, wenn du sie führst oder Offizier bist, und zählt Mitglieder pro Zone, wenn dein Addon ihn sendet.\n\nJeder im Olympus-Kanal empfängt es. %s\n\nHältst du es privat, wird nichts davon gesendet. Eine Bitte um einen Layerwechsel sendet trotzdem die Zone, in der du bist, und den gewünschten Layer.\n\nÄndere es jederzeit mit /oly location on oder /oly location off.",
	LOCATION_KEEP = "Privat halten",
	LOCATION_OFF = "Deine Zone und dein Layer bleiben privat: das Addon sendet keins von beiden. /oly location on teilt sie.",
	LOCATION_ON = "Du teilst deine Zone und deinen Layer im Olympus-Kanal. /oly location off beendet das.",
	LOCATION_SHARE = "Teilen",
	LOOT_ABOUT = "Von den Offizieren der Gilde geschrieben (dem Gildenmeister und dem Offiziersrang direkt darunter), gelesen von jedem Mitglied mit dem Addon, nur über Gildennachrichten: nie im Olympus-Kanal. Kein Bietfenster und kein Beute-Tool: Es hält nur fest, was die Offiziere entschieden haben.",
	LOOT_DROPS = "Die Beute deiner Gruppe in dieser Sitzung (klicken, um ihre Notiz zu schreiben)",
	LOOT_DROP_TIP = "Aus den eigenen Beutezeilen des Spiels, nur in dieser Sitzung auf deinem Bildschirm gespeichert. Ein Klick öffnet ihre Notiz: Nichts wird verteilt.",
	LOOT_EMPTY = "Noch keine Beutenotizen: Deine Offiziere schreiben sie nach den Entscheidungen eines Schlachtzugs.",
	LOOT_EMPTY_OFFICER = "Noch keine Beutenotizen: Schreib die erste nach den Entscheidungen eines Schlachtzugs.",
	LOOT_ITEM_N = "Gegenstand %d",
	LOOT_LINK = "Beutenotizen von <%s>",
	LOOT_LINK_TIP = "Das Buch der Beuteentscheidungen deiner Gilde, geschrieben von ihren Offizieren: welcher Gegenstand an wen ging und warum, damit der nächste Schlachtzug bei der Entscheidung der letzten Woche anfängt. Auch Punkte, falls deine Gilde sie nutzt: Zahlen, die die Offiziere von Hand festlegen. Keine Gebote, kein Würfeln, kein Gold: Hier wird nichts verteilt.",
	LOOT_NOTE_FOR = "Beutenotiz für [%s] > %s: warum es dorthin ging und wie es weitergeht.",
	LOOT_NOTE_PROMPT = "Beutenotiz: welcher Gegenstand an wen ging und warum (die Entscheidung, bei der der nächste Schlachtzug anfängt).",
	LOOT_NOTE_TIP = "Geschrieben von %s, %s.",
	LOOT_OFFICERS_ONLY = "Nur die Offiziere deiner Gilde (der Gildenmeister und der Offiziersrang direkt darunter) schreiben Beutenotizen und Punkte.",
	LOOT_POINTS_BAD = "Punkte gehen von -%d bis %d.",
	LOOT_POINTS_BY = "Festgelegt von %s, %s.",
	LOOT_POINTS_CLEARED = "%s: Punkte für deine Gilde gelöscht.",
	LOOT_POINTS_DONE = "%s: %d Punkte, an deine Gilde gesendet.",
	LOOT_POINTS_NOT_MEMBER = "%s ist nicht in der Mitgliederliste deiner Gilde.",
