	RANK_RULES_SCORE = "Wertung",
	RANK_RULES_VISIBILITY = "Wer sie sehen kann",
	RANK_RULE_ARENA_EVIDENCE = "Die Rangliste wird aus aufbewahrten gewerteten Kampfaufzeichnungen neu aufgebaut. Eine fehlende oder abgelehnte Aufzeichnung erzeugt kein Ergebnis.",
	RANK_RULE_ARENA_LIMITS = "Ein gewerteter Kampf braucht im Schnitt mindestens %d Sekunden pro Runde. Es zählen höchstens %d Kämpfe pro Spieler und Servertag und %d Kämpfe gegen denselben Gegner in %d Tagen. Proben und unbestätigte Kämpfe zählen nicht.",
	RANK_RULE_ARENA_ORDER = "Gesamtränge nutzen die höhere Wertung, dann mehr gewertete Kämpfe, dann den Namen; gleiche Wertungen teilen sich einen Platz. Zeitraumansichten nutzen gewonnene Wertung, Siege, weniger Niederlagen, aktuelle Wertung, dann den Namen.",
	RANK_RULE_ARENA_REPEAT = "Wiederholte Kämpfe zwischen demselben Paar innerhalb von %d Stunden zählen fortschreitend mit 1, 1/2, 1/4 und so weiter.",
	RANK_RULE_ARENA_SCORE = "Ein Kämpfer ohne übernommene Wertung beginnt bei %d. Zwischen den Saisons bewegt sich eine behaltene Wertung zur Hälfte zurück zu %d. K=%d gilt nur, solange der Kämpfer nicht eingependelt ist und weniger als %d gewertete Kämpfe hat; ein eingependelter Kämpfer kann daher außerhalb von %d beginnen und nutzt K=%d, oder K=%d ab Wertung %d. Jede Stufe Unterschied zählt als %d Wertungspunkte; der gesamte Abstand des erwarteten Ergebnisses ist bei %d gedeckelt.",
	RANK_RULE_ARENA_TITLE = "Arenawertung",
	RANK_RULE_ARENA_VISIBILITY = "Die Spiele-Mitarbeiter sehen sie immer. Mitglieder sehen sie nur, solange der Arena-Schalter eines berechtigten Veröffentlichers offen ist.",
	RANK_RULE_BONES_EVIDENCE = "Nur übereinstimmende signierte Spielhälften, die dieser Client aufbewahrt, zählen. Fehlende Hälften bleiben unbekannt.",
	RANK_RULE_BONES_LIMITS = "Ein Spiel braucht mindestens %d Sekunden. Es zählen höchstens %d Spiele pro Spieler und Servertag und %d Spiele gegen denselben Gegner in %d Tagen.",
	RANK_RULE_BONES_ORDER = "Mehr Siege kommen zuerst; bei Gleichstand zählen weniger Spiele, dann der frühere Zeitpunkt, zu dem diese Siegzahl erreicht wurde, dann der Name. Champion und Podium des abgeschlossenen Vormonats werden separat aufbewahrt.",
	RANK_RULE_BONES_SCORE = "Der aktuelle Kalendermonat wertet bestätigte Siege von Spieler gegen Spieler. Übung, Spiele gegen die Bank, Twinks desselben Besitzers, verborgene Spieler und Aufzeichnungen, deren zwei signierte Hälften nicht übereinstimmen, zählen nicht.",
	RANK_RULE_BONES_TITLE = "Knochenwurf-Rangliste",
	RANK_RULE_BONES_VISIBILITY = "Die Spiele-Mitarbeiter sehen sie immer. Mitglieder sehen sie nur, solange der Knochenwurf-Schalter eines berechtigten Veröffentlichers offen ist.",
	RANK_RULE_CHURCH_EVIDENCE = "Nur bestätigte Aufzeichnungen über Rekruten und späteres Bleiben in den Büchern der Kirche zählen. Fehlende Aufzeichnungen sind unbekannt und erzeugen keine Punkte.",
	RANK_RULE_CHURCH_FULLNESS_ORDER = "Mehr abgeschlossene zählende Tage kommen zuerst. Bei Gleichstand zählt der höhere Durchschnitt der zählenden Tagesdurchschnitte, dann der Gildenname.",
	RANK_RULE_CHURCH_FULLNESS_TITLE = "Rangliste der Gildenfülle",
	RANK_RULE_CHURCH_FULLNESS_VISIBILITY = "Das ist privat für das Publikum der Kirche; es ist nicht Teil der öffentlichen Kirchenrangliste.",
	RANK_RULE_CHURCH_ORDER = "Höhere Gesamtpunktzahl kommt zuerst; bei Gleichstand zählen höhere eigene Punkte, dann der Name. Die Zeiträume Woche, 30 Tage und gesamt zählen nur Nachweise mit Datum in diesem Zeitraum.",
	RANK_RULE_CHURCH_SCORE = "Ein bestätigter Rekrut bringt %d Punkte. Ein Rekrut, der nach %d Tagen noch in Olympus ist, bringt %d mehr. Ein Anführer erhält außerdem %d%%, %d%% und %d%% der eigenen Punkte, die auf den ersten drei Ebenen unter ihm verdient wurden; Anteile summieren sich nicht auf.",
	RANK_RULE_CHURCH_TITLE = "Rangliste des Kirchendienstes",
	RANK_RULE_CHURCH_VISIBILITY = "Das Publikum der Kirche sieht die volle Rangliste. Die öffentliche Seite zeigt nur zugestimmte Zeilen, solange der berechtigte Veröffentlichungsschalter offen ist.",
	RANK_RULE_CRAFT_EVIDENCE = "Auftraggeber und Handwerker signieren denselben abgeschlossenen Auftrag. Bei Uneinigkeit gilt die niedrigere beobachtete Seltenheit; eine einseitige Behauptung kommt nie in die Rangliste.",
	RANK_RULE_CRAFT_LIMITS = "Höchstens %d Lieferungen zwischen demselben Auftraggeber und Handwerker zählen pro Tag, und kein Spieler kann an einem Tag mehr als %d Handwerksaufzeichnungen hinzufügen.",
	RANK_RULE_CRAFT_ORDER = "Mehr Punkte stehen zuerst, dann mehr verschiedene Kunden, dann mehr Lieferungen, dann der Charaktername.",
	RANK_RULE_CRAFT_SCORE = "Eine bestätigte Lieferung beginnt bei 10 Punkten. Größere Mengen geben einen begrenzten, unterproportionalen Bonus; ungewöhnliche, seltene, epische und legendäre Ergebnisse geben steigende Seltenheitspunkte. Ein Rezept nur zu kennen, gibt keine Punkte.",
	RANK_RULE_CRAFT_TITLE = "Rangliste des Handwerksdienstes",
	RANK_RULE_CRAFT_VISIBILITY = "Die signierte Aufzeichnung wird von Clients, die sie haben, aufbewahrt und weitergeleitet, sodass die monatliche globale Rangliste nicht erfordert, dass einer der ursprünglichen Spieler online bleibt.",
	RANK_RULE_DEBTORS_EVIDENCE = "Nur bestätigte Einträge im Gebührenbuch, die das Gebührenpult oder seine letzte private Antwort hält, zählen. Unbestätigte Einträge warten außerhalb der Rangliste.",
	RANK_RULE_DEBTORS_ORDER = "Mehr überfälliges Kupfer kommt zuerst, dann mehr insgesamt geschuldetes Kupfer, dann der Name. Die Einzugsstufe wechselt zum Fälligkeitszeitpunkt, nach %d Stunden und nach %d Stunden.",
	RANK_RULE_DEBTORS_SCORE = "Das ist keine Ehrenrangliste. Eine bestätigte Gildengebühr ist %d Stunden nach dem abgeschlossenen Direktverkauf fällig. Offene Gebühren werden nach Handwerker gruppiert, wobei Gesamtschuld und bereits überfällige Beträge getrennt geführt werden.",
	RANK_RULE_DEBTORS_TITLE = "Einzugsreihenfolge der Handwerksgebühren",
	RANK_RULE_DEBTORS_VISIBILITY = "Nur die bestehenden privaten Leser des Gebührenbuchs können sie sehen. Nichts hier veröffentlicht Schulden oder bewegt automatisch Gold.",
	RANK_RULE_DONORS_DUES = "Wenn das Buch des Schatzmeisters außerhalb seiner privaten Ansicht geteilt wird, wird der mögliche Anteil der Wochenbeiträge entfernt. Andere Verwalterbücher zeigen zählende Gaben wie erfasst.",
	RANK_RULE_DONORS_EVIDENCE = "Dieser Client bewertet die Bücher, die er gerade hat. Ein fehlendes oder älteres Buch ist ein fehlender oder älterer Nachweis, nicht null.",
	RANK_RULE_DONORS_ORDER = "Höheres zählendes Kupfer kommt zuerst; gleiche Summen werden nach Namen geordnet.",
	RANK_RULE_DONORS_SCORE = "Zählende eingehende Gaben werden in Kupfer addiert. Zurückgesandte, ausgehende, übertragene und ausgeschlossene Buchzeilen erhöhen die Summe nicht.",
	RANK_RULE_DONORS_TITLE = "Spenderrangliste",
	RANK_RULE_DONORS_VISIBILITY = "Der König, seine Truchsesse und die Verwalter können sie sehen. Andere Mitglieder sehen sie nur, solange der Ranglistenschalter des Königs offen ist.",
	RANK_RULE_GUILD_TREASURY_EVIDENCE = "Jede Zeile nutzt den neuesten berechtigten Schnappschuss, der hier liegt. Ausstehende Gegenstandspreise machen ihre Summe zu einem Mindestbetrag. Fehlende Gilden und Gegenstände ohne Preis bleiben unbekannt.",
	RANK_RULE_GUILD_TREASURY_ORDER = "Die höhere Summe kommt zuerst; bei Gleichstand zählt die höhere bekannte Durchschnittsstufe, dann der Gildenname. Die Föderale Schatzkammer wird separat gezeigt und belegt keinen Platz.",
	RANK_RULE_GUILD_TREASURY_SCORE = "Die Summe jeder Gilde ist das Gold in ihrem berechtigten Bank-Schnappschuss plus der bekannte eingestellte oder Händlerwert jedes Gegenstands. Gegenstände ohne Preis werden nicht in den Wert hineinerfunden.",
	RANK_RULE_GUILD_TREASURY_TITLE = "Rangliste der Gildenschatzkammern",
	RANK_RULE_GUILD_TREASURY_VISIBILITY = "Nur das bestehende private Publikum der Gildenschatzkammern kann diese Rangliste sehen. Sie wird nicht an die Armee veröffentlicht.",
	RANK_RULE_LEVEL_EVIDENCE = "Nur die Listen der besten Charaktere in frischen Gildenmeldungen, die dieser Client hält, sind enthalten. Das ist eine lokale Zensusansicht, keine Serverbestätigung.",
	RANK_RULE_LEVEL_ORDER = "Höhere Stufe kommt zuerst; gleiche Stufen werden nach Charaktername geordnet. Die Seite zeigt höchstens %d Charaktere, %d auf einmal.",
	RANK_RULE_LEVEL_SCORE = "Es gibt keine Punkte: Charaktere werden nach ihrer zuletzt gemeldeten Stufe geordnet.",
	RANK_RULE_LEVEL_TITLE = "Stufenrennen",
	RANK_RULE_LEVEL_VISIBILITY = "Jedes Olympus-Mitglied kann dieselbe Ranglistenseite sehen, gebaut aus den Meldungen, die sein Client gehört hat.",
	RANK_RULE_WANTED_BOUNTY = "Bei aktuellen gewerteten Nachweisen fügt ein gezählter Tod die Stufe des Opfers und seinen höchsten verifizierten Amtsbonus zum offenen Kopfgeld des Horde-Spielers hinzu: König 100, Hoher Rat 50, Gildenmeister 30, Legat 20, ein anderes Amt 10, Mitglied 0, bis zu einer Obergrenze des offenen Kopfgelds von %d. Eine aktuelle gewertete Wiederholung innerhalb von %d Minuten fügt weder Kopfgeld noch einen weiteren gezählten Kill hinzu. Ältere Kompatibilitätsnachweise ohne Wertungsfelder behalten ihr altes Verhalten: sie fügen einen historischen Kill und bis zu 1 Kopfgeldpunkt unter derselben Obergrenze hinzu; der aktuelle Schutz vor gewerteten Wiederholungen wird nicht angewandt.",
	RANK_RULE_WANTED_EVIDENCE = "Die lokalen Tafeln nutzen die eigenen aufbewahrten Zeilen dieses Clients und die verifizierten Zeilen, die Olympus-Mitglieder mit ihm geteilt haben; es sind keine vom Server bestätigten Summen. Fehlende Nachweise bleiben unbekannt. Alte Punktzahlen werden nur dort neu berechnet, wo aufbewahrte Fakten das Ergebnis beweisen; sonst bleibt die alte Summe archiviert, statt in die Rangliste hineingeraten zu werden.",
	RANK_RULE_WANTED_LIMITS = "Bei aktuellen gewerteten Nachweisen zählt die Stufenbasis für denselben Killer und dasselbe Ziel höchstens einmal in %d Minuten und Rache höchstens einmal in %d Stunden. Tode und Kills in Instanzen zählen nicht. Horde-Einträge ohne Kopfgeld und ohne Kill bleiben von der sichtbaren Gesucht-Liste fern.",
	RANK_RULE_WANTED_ORDER = "Gesucht wird nach höherem aktuellem offenem Kopfgeld geordnet, dann nach mehr gezählten Kills insgesamt, dann nach Namen. Monatliche und ewige Jäger werden nach mehr Punkten geordnet, dann nach dem früheren Zeitpunkt, zu dem diese Summe erreicht wurde, dann nach stabiler Identität. Nur eine signierte globale Top drei bestimmt die Jäger-Rahmen.",
	RANK_RULE_WANTED_SLAYER = "Ein aktueller gewerteter zählender Horde-Kill gibt einen Basispunkt pro %d Horde-Stufen, aufgerundet, plus das gesamte offene Kopfgeld und %d Punkte für eine berechtigte Rache. Rache muss den eigenen Tod dieses Spielers innerhalb von %d Tagen beantworten. Ein älterer Kompatibilitätsanspruch ohne Wertungsfelder zahlt nur das offene Kopfgeld, ohne Stufenbasis oder Rache.",
	RANK_RULE_WANTED_TITLE = "Gesucht- und Jäger-Ranglisten",
	RANK_RULE_WANTED_VISIBILITY = "Olympus-Mitglieder können diese Regeln und die Aufzeichnungen lesen, die ihr eigener Client hält. Nur der König, der signierte Hohe Rat und der Autor können die signierte globale Top drei veröffentlichen. Standortzeilen und Kartenmarkierungen unterliegen außerdem den separaten Sperren für das Teilen des Standorts und die Moderation.",
	RB_APOSTLE_1 = "Hey,\n\ndu bist jetzt einer der Zwölf Apostel der Missionskirche von Olympus. Zwölf. Mehr gibt es nicht. Das ist riesig.\n\nDie Aufgabe: neue Spieler zu Olympus bringen und ein Netzwerk von Missionaren aufbauen, die dasselbe tun.\n\nWas man sieht: Die drei besten Apostel der letzten 30 Tage tragen das Kreuz der Apostel, und jeder sieht es.",
	RB_APOSTLE_2 = "Was du bekommst:\n- Bis zu 12 eigene Missionare (Reiter Kirche, Benennen, oder Rechtsklick auf einen Spieler).\n- Den Reiter Kirche: die Rangliste, deine Zahlen, die Leute.\n- Den Raum der Apostel und die Kirchenräume im Chat.\n- Während du spielst, führt dein Addon das Buch der Kirche für alle.\n\nEine Regel: Benenne Leute, die es auch wirklich tun.",
	RB_APOSTLE_LAUNCH = "Okay, hör zu.\n\nDas Spiel ist live. Du bist einer von zwölf Aposteln in der ganzen Armee. Das ist riesig. Jetzt macht die Kirche ihrem Namen Ehre.\n\nGleiche Aufgabe: neue Spieler zu Olympus bringen und Missionare aufbauen, die dasselbe tun.\n\n- Benenne Missionare: bis zu 12 pro Person, im Reiter Kirche (Benennen) oder per Rechtsklick auf einen Spieler. Sie benennen ihre eigenen, bis zu fünf Ebenen unter dir. Höchstens 5.000 in der ganzen Kirche.\n- Punkte: 10 für jeden Spieler, der neu bei Olympus ist und über dich beitritt, 5 mehr, wenn er 7 Tage später noch da ist. Dazu von dem, was deine drei Ebenen darunter einbringen: 25% (erste Ebene), 10% aus der zweiten und 5% obendrein aus der dritten. Jemand unter dir kann dich überholen. Gut. Das heißt, es funktioniert.\n- Jemanden gebracht, den ein anderer Spieler eingeladen hat? Trag ihn ein: Er zählt, wenn er innerhalb von 14 Tagen einer Olympus-Gilde beitritt.\n- Die drei besten Apostel der letzten 30 Tage tragen das Kreuz.\n- Jemand hat aufgehört zu spielen? Entferne ihn. Die Leute, die er benannt hat, behalten ihre Plätze.\n\nEine Regel: nur echte neue Spieler. Twinks und Wechsel zwischen Olympus-Gilden zählen nie. Punkte gibt es nur im Spiel, niemals Gold.\n\nLass dein Addon an, während du spielst. Es führt das Buch der Kirche. Los geht's!",
	RB_APOSTLE_LAUNCH_TITLE = "Die Kirche zum Start",
	RB_APOSTLE_RED = "Unter Mein Profil, bei Aussehen, gibt es außerdem ein rotes Kreuz, das nur du siehst.",
	RB_APOSTLE_TITLE = "Apostel",
	RB_BACK = "< Alle Amtsbriefe",
	RB_BTN_CHURCH = "Kirche",
	RB_BTN_CRAFTERS = "Handwerker",
	RB_BTN_DECREES = "Erlasse",
	RB_BTN_GUILD = "Reiter Gilde",
	RB_BTN_THRONE = "Der Thron",
	RB_BTN_TREASURY = "Schatzkammer",
	RB_BTN_WAR = "Kriegsraum",
	RB_BTN_WATCH = "Die Wache",
	RB_CHURCHCORR = "Hey,\n\ndu bist jetzt der Kirchenkorrespondent von <%s>. Du bist dem Oberhaupt der Kirche unterstellt. Das bin ich.\n\nDie Aufgabe: deine Gilde voll halten.\n\nWas man sieht: kein neuer Rahmen.\n\nWas du bekommst:\n- Den Reiter Kirche: die Rangliste, deine eigenen Zahlen und die Leute.\n- Trag einen Rekruten ein, den du gebracht hast, bis zu 15 gleichzeitig offen. Er zählt für dich, wenn er innerhalb von 14 Tagen einer Olympus-Gilde beitritt und neu bei Olympus ist.\n- Den Kirchenraum im Chat.\n\nIn der Rangliste zählen deine Tage in Folge mit über 950 Mitgliedern, ab deiner Ernennung.\n\nEine Regel: Lass deine Gilde wachsen, aber nie, indem du Leute aus einer anderen Olympus-Gilde abziehst.",
	RB_CHURCHCORR_TITLE = "Kirchenkorrespondent",
	RB_CHURCH_LETTER_LINK = "Dein Brief vom König",
	RB_CHURCH_LETTER_TIP = "Der Brief deines Amts: die Aufgabe, was man sieht und was es freischaltet.",
	RB_CORR_ARTISANRY = "Hey,\n\ndu bist jetzt der Handwerks-Korrespondent von <%s>. Der beste Freund der Handwerker.\n\nDie Aufgabe: deinen Gildenkameraden helfen, Handwerker zu finden, und Aufträge, Materialien und Vorräte zu denen bringen, die sie brauchen.\n\nWas man sieht: das Schildabzeichen der Handwerksvereinigung an deinem Porträt und neben deinem Namen.\n\nWas du bekommst:\n- Die Handwerkertafel, einen Klick von deinem Reiter Gilde entfernt.\n- Den Raum der Handwerksvereinigung und den Raum Meister & Korrespondenten.\n\nDie eigenen Werkzeuge des Amts gibt es noch nicht. Fürs Erste bist du die Person, die man fragt.\n\nEine Regel: Niemand in deiner Gilde bleibt ohne Handwerk hängen.",
	RB_CORR_ARTISANRY_TITLE = "Handwerks-Korrespondent",
	RB_CORR_CHURCHDEPT = "Hey,\n\ndu bist jetzt der Korrespondent von <%s> für die Missionskirche.\n\nDie Aufgabe: neue Spieler reinholen und helfen, deine Gilde voll zu halten.\n\nWas man sieht: das Schildabzeichen der Missionskirche an deinem Porträt und neben deinem Namen.\n\nWas du bekommst: den Titel und den Amtsraum. Ehrlich gesagt, das war's. Der Titel zeigt allen, wer der Kirchenkontakt deiner Gilde ist.\n\nFür den eigenen Raum der Kirche und die Rekrutierungszahlen brauchst du auch einen Platz in der Kirche. Dein Gildenmeister benennt den Kirchenkorrespondenten im Reiter Kirche, oder ein Apostel benennt dich zum Missionar.\n\nEine Regel: Hol echte neue Spieler rein. Twinks und Wechsel zwischen Olympus-Gilden zählen nie.",
	RB_CORR_CHURCHDEPT_TITLE = "Korrespondent der Missionskirche",
	RB_CORR_HERALDRY = "Okay,\n\ndu bist jetzt der Heraldik-Korrespondent von <%s>. Du bist die Stimme deiner Gilde.\n\nDie Aufgabe: die Erlasse, die Agenda und die Sammelrufe deiner Gilde leiten und dafür sorgen, dass die Leute zu Events und Streams kommen.\n\nWas man sieht: das Schildabzeichen des Heroldsamts an deinem Porträt und neben deinem Namen.\n\nWas du bekommst:\n- Jeden Erlass für deine Gilde: Rufe zu den Waffen, Sammelrufe, königliche Erlasse, Wappenrock-Inspektionen.\n- Die Agenda deiner Gilde.\n- Den Raum des Heroldsamts und den Raum Meister & Korrespondenten.\n\nNur deine Gilde. Die ganze Armee gehört der Krone und dem Hohen Rat.\n\nEine Regel: Mach keinen falschen Alarm. Ruf, wenn es darauf ankommt.",
	RB_CORR_HERALDRY_TITLE = "Heraldik-Korrespondent",
	RB_CORR_JUSTICE = "Hey,\n\ndu bist jetzt der Justiz-Korrespondent von <%s>. Du sorgst für Frieden.\n\nDie Aufgabe: den Chat deiner Gilde im Blick behalten, Probleme regeln und mit deinem Gildenmeister und dem Rat der Justiz zusammenarbeiten.\n\nWas man sieht: das Schildabzeichen des Rats der Justiz an deinem Porträt und neben deinem Namen.\n\nWas du bekommst:\n- Das ganze Pult der Wache (Reiter Die Wache) für die Mitglieder deiner Gilde unter dir: Verwarnungen, Auszeiten, die Beobachtungsliste, Meldungen.\n- Wenn ich nach der Abstimmung des Hohen Rats einen Fall bestätige, setzt du ihn in deiner Gilde um. Das Addon wirft nie jemanden von selbst raus.\n- Den Raum des Rats der Justiz.\n\nEine Regel: Sei fair. Gleiche Regeln für deine Freunde.",
	RB_CORR_JUSTICE_TITLE = "Justiz-Korrespondent",
	RB_CORR_TREASURY = "Hey,\n\ndu bist jetzt der Schatzkammer-Korrespondent von <%s>. Stark.\n\nDie Aufgabe: die Schatzkammer-Aufzeichnungen deiner Gilde und das Teilen der Bank in Ordnung halten, zusammen mit deinem Gildenmeister und der Bundesschatzkammer.\n\nWas man sieht: das Schildabzeichen der Bundesschatzkammer an deinem Porträt und neben deinem Namen.\n\nWas du bekommst:\n- Die Bank deiner Gilde im Addon. Öffne die Gildenbank mit eingeschaltetem Addon, und es macht einen Schnappschuss. Es bewegt nie etwas. Dein Gildenmeister entscheidet, ob die ganze Gilde die Bank sieht.\n- Den Raum der Bundesschatzkammer und den Raum Meister & Korrespondenten.\n\nEine Regel: Das Gold der Gilde gehört der Gilde. Halte die Bücher sauber.",
	RB_CORR_TREASURY_TITLE = "Schatzkammer-Korrespondent",
	RB_CORR_WAR = "Okay,\n\ndu bist jetzt der Kriegs-Korrespondent von <%s>. Du bist derjenige, der die Schlachtzüge möglich macht.\n\nDie Aufgabe: die Schlachtzüge und PvP-Operationen deiner Gilde organisieren, ihre Schlachtzugsgruppen und Einsatzberichte.\n\nWas man sieht: das Schildabzeichen des Kriegsamts an deinem Porträt und neben deinem Namen.\n\nWas du bekommst:\n- Offiziersrechte im Kriegsraum deiner Gilde (Reiter Das Reich): Operationen, Schlachtzugsgruppen, Posten, Einsatzberichte.\n- Den Raum des Kriegsamts und den Raum Meister & Korrespondenten.\n\nAlles davon innerhalb deiner eigenen Gilde.\n\nEine Regel: Plan es, ruf es aus, sei dabei.",
	RB_CORR_WAR_TITLE = "Kriegs-Korrespondent",
	RB_COUNCIL = "Okay, hör zu.\n\nDu bist jetzt im Hohen Rat. Das ist riesig. Diesen Rang kann man sich nicht erfarmen. Du wurdest ausgewählt. Lass uns das nicht bereuen.\n\nDie Aufgabe: Olympus mit mir führen. Urteilen, die Armee rufen, auf den Laden aufpassen.\n\nWas man sieht: die silbernen Flügel an deinem Porträt und der silberne Drache vor deinem Namen im Chat. Unter Mein Profil, Symbole, kannst du ein Symbol dahinter hinzufügen.\n\nWas du bekommst:\n- Königliche Erlasse, Wappenrock-Inspektionen, Rufe zu den Waffen und Sammelrufe für die ganze Armee.\n- Die Wache: die Meldungen des Rats und eine Stimme bei jedem Urteil. Ich habe das letzte Wort.\n- Bis zu 10 eigene Olympus-Moderatoren.\n- Apostel benennen und die öffentliche Rangliste der Kirche öffnen.\n- Legaten für die Gilde des Königs ernennen, im Reiter Thron.\n- Den Raum des Hohen Rats.\n\nEine Regel: Du handelst für Olympus, nicht für deine Gilde.",
	RB_COUNCIL_ARTISANRY = "Du leitest die Handwerksvereinigung. In deinem Amtsraum sind die Handwerks-Korrespondenten aller Gilden. Die eigenen Werkzeuge des Amts kommen später.",
	RB_COUNCIL_BADGE = "Das Schildabzeichen deines Amts erscheint auch an deinem Porträt.",
	RB_COUNCIL_CHURCHDEPT = "Du leitest das Amt der Kirche. In deinem Amtsraum sind die Kirchenkorrespondenten aller Gilden, und die Rangliste im Reiter Kirche steht dir offen.",
	RB_COUNCIL_HERALDRY = "Du leitest das Heroldsamt. Du postest die Agenda des Königs für die ganze Armee. In deinem Amtsraum sind die Heraldik-Korrespondenten aller Gilden.",
	RB_COUNCIL_JUSTICE = "Du sitzt im Rat der Justiz. Ich führe den Vorsitz. Wenn ich nicht da bin, übernimmt das ein Ratsmitglied des Hohen Rats. In deinem Amtsraum sind die Justiz-Korrespondenten aller Gilden.",
	RB_COUNCIL_TITLE = "Der Hohe Rat",
	RB_COUNCIL_TREASURY = "Du leitest die Bundesschatzkammer. In deinem Amtsraum sind der Bundesschatzmeister und die Schatzkammer-Korrespondenten aller Gilden.",
	RB_COUNCIL_WAR = "Du leitest das Kriegsamt. Im Kriegsraum deiner eigenen Gilde zählst du als Offizier. In deinem Amtsraum sind die Kriegs-Korrespondenten aller Gilden.",
	RB_GM_ARTISANRY = "Korrespondent der Handwerksvereinigung",
	RB_GM_ARTISANRY_JOB = "Bringt deine Handwerker mit den Leuten zusammen, die sie brauchen.",
	RB_GM_ARTISANRY_SHOWS = "Das Schildabzeichen der Handwerksvereinigung an seinem Porträt und neben seinem Namen.",
	RB_GM_ARTISANRY_UNLOCKS = "Einen Link zur Handwerkertafel und den Raum der Handwerksvereinigung. Noch keine zusätzliche Macht.",
	RB_GM_BANK = "Gildenbank",
