	RB_GM_JUSTICE_UNLOCKS = "Das ganze Pult der Wache für die Mitglieder deiner Gilde unter ihm. Den Raum des Rats der Justiz.",
	RB_GM_LEGATES = "Legaten (%d von %d)",
	RB_GM_LEGATES_JOB = "Jeder führt eine Schlachtzugsgruppe: sich selbst und bis zu 39 Gildenkameraden, die zugestimmt haben, 40 insgesamt.",
	RB_GM_LEGATES_SHOWS = "Das Legaten-Schildabzeichen an seinem Porträt und dasselbe Abzeichen neben seinem Namen.",
	RB_GM_LEGATES_UNLOCKS = "Seine Gruppe im Kriegsraum (Reiter Das Reich): Soldaten zuweisen und entfernen, Schlachtzugseinladungen, einen privaten Truppchat. Die Räume Meister & Legaten.",
	RB_GM_MUST = "Ernenne diese",
	RB_GM_OPEN = "Okay, hör zu.\n\nDu führst eine Gilde in Olympus. Das ist eine große Sache. Olympus ist die Armee, aber deine Gilde ist der Ort, an dem die Leute wirklich leben.\n\nDu schaffst es nicht allein, und das sollst du auch nicht. Ernenne deine Leute. Jede Zeile unten öffnet sich mit einem Klick und hakt sich selbst ab, sobald sie erledigt ist. Ein Titel pro Person, und nur Mitglieder deiner eigenen Gilde.",
	RB_GM_PREVIEW = "(Im eigenen Brief eines Gildenmeisters hakt sich jede Zeile selbst ab, und ihr Knopf öffnet den Schritt.)",
	RB_GM_SHOWS = "Sichtbar: %s",
	RB_GM_TITLE = "Gildenmeister: Ernenne deine Leute",
	RB_GM_TODO = "[  ] %s",
	RB_GM_TREASURY = "Korrespondent der Bundesschatzkammer",
	RB_GM_TREASURY_JOB = "Hält die Schatzkammer-Aufzeichnungen deiner Gilde und das Teilen der Bank in Ordnung, mit dir und der Bundesschatzkammer.",
	RB_GM_TREASURY_SHOWS = "Das Schildabzeichen der Bundesschatzkammer an seinem Porträt und neben seinem Namen.",
	RB_GM_TREASURY_UNLOCKS = "Den Bankbestand deiner Gilde und ihre Schatzkammer-Seite. Den Raum der Bundesschatzkammer.",
	RB_GM_UNLOCKS = "Schaltet frei: %s",
	RB_GM_WAR = "Korrespondent des Kriegsamts",
	RB_GM_WAR_JOB = "Leitet die Schlachtzüge und PvP-Operationen deiner Gilde.",
	RB_GM_WAR_SHOWS = "Das Schildabzeichen des Kriegsamts an seinem Porträt und neben seinem Namen.",
	RB_GM_WAR_UNLOCKS = "Offiziersrechte in deinem Kriegsraum: Operationen, Schlachtzugsgruppen, Posten, Einsatzberichte. Den Raum des Kriegsamts.",
	RB_GM_WATCHERS = "Wächter",
	RB_GM_WATCHERS_TEXT = "Deine Hauptleute haben die Wache schon. Wächter bekommen sie auch, für deine Mitglieder unter ihnen.",
	RB_GM_WORTH = "Lohnt sich auch",
	RB_GUILD_TAB_LINK = "Dein Brief vom König: %d von %d ernannt",
	RB_HAND = "Okay,\n\nich habe dich zu einer Hand des Königs gemacht. Das ist eine große Sache. Du nutzt meine Werkzeuge, in meinem Namen.\n\nWas man sieht: kein neuer Rahmen. Der Reiter Thron öffnet sich für dich.\n\nWas du bekommst:\n- Lords rufen: ein Appell aller Lords und Hauptleute, die online sind.\n- Königliche Inspektion: Die Armee prüft die Wappenröcke um sich herum.\n- Die Agenda des Königs und Vox-Populi-Umfragen.\n- Die Tore: wohin neue Rekruten gehen.\n- Rufe zu den Waffen und Sammelrufe für die ganze Armee.\n\nWas meins bleibt: die Liste der Hände, die Schreiben, der Hof und die Begnadigungen.\n\nEine Regel: Spamme die Armee nicht zu. Jeder Ruf, den du sendest, erscheint bei allen auf dem Bildschirm.",
	RB_HAND_TITLE = "Hand des Königs",
	RB_HELP = "  /oly duties - die Briefe des Königs für deine Ämter erneut lesen",
	RB_KEEPER = "Hey,\n\nich habe dich zum Verwahrer der Schatzkammer ernannt. Ich vertraue dir das Gold an. Mach's nicht komisch.\n\nDie Aufgabe: einen Teil der Schatzkammer auf deinem Charakter halten, neben dem Schatzmeister.\n\nWas man sieht: kein neuer Rahmen.\n\nWas du bekommst:\n- Dein eigenes Buch im Reiter Schatzkammer. Gold und Gegenstände, die dir Leute per Handel oder Post geben, zählen von selbst als Spenden, sobald du dem Teilen zustimmst.\n- Gold zwischen zwei Verwahrern ist eine Überweisung, nie eine Spende.\n- Was du beim Spielen verdienst, bleibt deins. Ein Verkauf oder ein Kauf wird als nicht gezählt eingetragen.\n\nEs gibt höchstens fünf Verwahrer, und ich kann es jederzeit zurücknehmen.\n\nEine Regel: Gespendetes Gold darfst du nie selbst ausgeben.",
	RB_KEEPER_TITLE = "Verwahrer der Schatzkammer",
	RB_LAUNCH = "Okay, hört zu.\n\nDie Beta ist vorbei. Es ist so weit. Olympus ist live.\n\nVor nicht allzu langer Zeit waren das ein paar Gilden und eine Idee. Und jetzt seht es euch an. Eine Armee, ein Reich, und jeder Einzelne von euch ist dabei. Das ist riesig. Ganz ehrlich.\n\nDiesmal ist nicht viel neu. Jedes Amt bekommt jetzt seinen eigenen Brief, und Gildenmeister bekommen in ihrem eine Checkliste. Das war's. Der Rest liegt bei euch.\n\nNoch eine Sache. Fern hat uns eine Gildenhalle gebaut: olympus.roachcouncil.com. Wenn ihr im Discord seid, meldet euch an und geht durch die Tore. Danke, Fern. Wirklich.\n\nSeid cool im Chat. Helft den Neuen. Bringt eure Freunde mit.\n\nViel Spaß beim Spielen. Ich mein's ernst. Los geht's!",
	RB_LAUNCH_TITLE = "Die Tore sind offen",
	RB_LEGATE = "Okay, hör zu.\n\nDu bist jetzt ein Legat von <%s>. Los geht's!\n\nDie Aufgabe: eine Schlachtzugsgruppe führen. Du und bis zu 39 Gildenkameraden, die zugestimmt haben, 40 insgesamt. Bring sie zu Events, Schlachtzügen und Kriegen.\n\nWas man sieht: das Legaten-Schildabzeichen an deinem Porträt und dasselbe Abzeichen neben deinem Namen.\n\nWas du bekommst:\n- Deine Gruppe im Kriegsraum (Reiter Das Reich): Soldaten zuweisen und entfernen, die, die online sind, in den Schlachtzug einladen, einen privaten Truppchat.\n- Die Räume Meister & Legaten im Chat.\n\nNichts passiert automatisch: keine Gildeneinladung, kein Rauswurf, keine Beförderung. Gruppen sind freiwillig, und die Leute können mit einem anderen Anführer spielen.\n\nEine Regel: Trag nur Leute ein, die Ja gesagt haben.",
	RB_LEGATE_TITLE = "Legat",
	RB_LINK = "Amtsbriefe",
	RB_LINK_PREVIEW = "Amtsbriefe (Vorschau)",
	RB_MISSIONARY = "Hey,\n\ndu bist jetzt ein Missionar der Kirche, im Netzwerk von %s. Willkommen.\n\nDie Aufgabe: neue Spieler zu Olympus bringen.\n\nWas man sieht: Die drei besten Missionare der letzten 30 Tage tragen den Hirtenstab.\n\nWas du bekommst:\n- Lade neue Spieler in deine Gilde ein, und das Addon zählt es von selbst, sobald das Addon eines anderen Spielers es bestätigt.\n- Jemanden gebracht, den ein anderer Spieler eingeladen hat? Trag ihn im Reiter Kirche ein. Er zählt, wenn er innerhalb von 14 Tagen einer Olympus-Gilde beitritt.\n- Bis zu 12 eigene Missionare, außer du bist schon fünf Ebenen tief.\n- Den Reiter Kirche, den Raum Apostel & Missionare und den Kirchenraum.\n\nPunkte: 10 für jeden neuen Spieler, 5 mehr, wenn er 7 Tage bleibt.\n\nEine Regel: nur echte neue Spieler. Twinks und Wechsel zwischen Olympus-Gilden zählen nie.",
	RB_MISSIONARY_TITLE = "Missionar",
	RB_MODERATOR = "Okay, hör zu.\n\nDu bist jetzt ein Olympus-Moderator. Du hältst die Chats der ganzen Armee sauber. Das ist ein echter Job.\n\nDie Aufgabe: dich um Beleidigungen, Beschimpfungen, Spam und Betrug in den Olympus-Chats kümmern.\n\nWas man sieht: nichts an deinem Porträt.\n\nWas du bekommst:\n- Die Chatmoderation der Wache: Zeilen löschen und Leuten überall in Olympus eine Auszeit geben, andere Gildenmeister eingeschlossen. Nie dem Meister von <Olympus> oder jemandem über dir.\n- Den Raum der Wache, mit dem Hohen Rat, den anderen Moderatoren und mir.\n\nDu behältst das, solange der, der dich ernannt hat, dich auf seiner Liste lässt.\n\nEine Regel: Was du im Team siehst, bleibt im Team.",
	RB_MODERATOR_TITLE = "Olympus-Moderator",
	RB_NONE = "Noch kein Brief für ein Amt dieses Charakters.",
	RB_NOT_LIVE = "Die Amtsbriefe sind noch nicht raus.",
	RB_PAGE_NOTE = "Ein Brief vom König für jedes Amt, das dieser Charakter innehat, beim ersten Mal, wenn er es innehat. Sie bleiben hier und unter Mein Profil > Briefe, zum erneuten Lesen.",
	RB_PAGE_TITLE = "Briefe für deine Ämter",
	RB_PREVIEW_DEPT = "%s: %s",
	RB_PREVIEW_HEAD = "Vorschau: jeder Amtsbrief",
	RB_PREVIEW_LETTER = "Vorschau: Nichts wird gespeichert oder gesendet, und die Knöpfe tun nichts.",
	RB_PREVIEW_NOTE = "Für den Autor und den König: jeder Brief so, wie sein Empfänger ihn liest. Eine Vorschau speichert nichts, sendet nichts und markiert nichts als gelesen, und ihre Knöpfe tun nichts.",
	RB_PREVIEW_OFF = "Noch nicht raus: Niemand bekommt einen Brief, bis der Autor sie einschaltet.",
	RB_READY = "Ein Brief vom König wartet: %s. Öffne ihn mit /oly duties oder unter Mein Profil > Briefe.",
	RB_REALM_BACK = "< Zurück zum Reich",
	RB_SITE_TITLE = "Die Tore von Olympus",
	RB_STEWARD = "Hey,\n\ndu bist jetzt mein Truchsess. Das heißt, wenn ich nicht da bin, bist du ich. Kein Druck.\n\nDie Aufgabe: den Thron in meinem Namen am Laufen halten.\n\nWas man sieht: kein neuer Rahmen. Deine Macht liegt im Reiter Thron.\n\nWas du bekommst:\n- Den Thron, im Auftrag des Königs: Appell, Königliche Inspektion, die Agenda, Vox Populi, die Tore.\n- Eigene Hände. Du ernennst sie, du nimmst sie zurück.\n- Die Schalter und Verwahrer der Schatzkammer und den wöchentlichen Beitragsbetrag.\n- Jede Art von Erlass, für die ganze Armee.\n- Den Raum Sekretariat, mit mir.\n\nWas meins bleibt: meine eigenen Hände, der Hof, die Schreiben und die Begnadigungen.\n\nEine Regel: Handle so, als würde ich zusehen. Denn das werde ich.",
	RB_STEWARD_TITLE = "Mein Truchsess",
	RB_TREASURER = "Hey,\n\ndu bist der Bundesschatzmeister. Du hältst das Gold von Olympus. Ja. Alles davon.\n\nDie Aufgabe: die Schatzkammer ehrlich halten, und in einem einzigen Buch.\n\nWas man sieht: der Drachenrahmen des Schatzmeisters an deinem Porträt.\n\nWas du bekommst:\n- Den Reiter Schatzkammer und dein Buch: Jeder Handel und jeder Brief mit Gold oder Gegenständen kommt von selbst hinein, sobald du dem Teilen zustimmst.\n- Die wöchentlichen Beiträge, an dich bezahlt. Wer bezahlt hat, bleibt privat: Der König und die Hauptleute jeder Gilde sehen es, nie die Armee.\n- Den Raum des Hohen Rats und den Raum der Bundesschatzkammer.\n\nWas du beim Spielen verdienst, gehört dir. Es kommt nie ins Buch.\n\nEine Regel: Jedes Kupfer rein, jedes Kupfer raus. Im Buch.",
	RB_TREASURER_TITLE = "Der Bundesschatzmeister",
	RB_WATCHER = "Hey,\n\ndein Gildenmeister hat dich zum Wächter von <%s> ernannt. Du hilfst, den Chat sauber zu halten.\n\nDie Aufgabe: den Chat deiner Gilde im Auge behalten und eingreifen, wenn jemand eine Grenze überschreitet.\n\nWas man sieht: nichts an deinem Porträt.\n\nWas du bekommst: das ganze Pult der Wache (Reiter Die Wache) für die Mitglieder deiner Gilde unter dir: Verwarnungen, Auszeiten, die Beobachtungsliste, Meldungen und Fälle.\n\nDu bleibst Wächter, solange dein Gildenmeister dich auf seiner Liste lässt.\n\nEine Regel: Erst verwarnen. Von da an steigen die Auszeiten: eine Stunde, ein Tag, eine Woche.",
