	HONOR_LETTER = { ["apostle"] = "Hey,\n\nIn den letzten dreißig Tagen hat kaum ein Apostel so viele Leute zu Olympus gebracht wie du. Du bist %s, und das Kreuz gehört dir, solange du unter den ersten drei bleibst.\n\nBleib dem Glauben treu. Und bring weiter Leute.", ["arena"] = "Okay, hör zu.\n\nDu bist in die Arena gegangen und hast alle geschlagen. Nicht die meisten. Alle. Also bist du jetzt %s, und der Greif gehört dir.\n\nKleine Warnung: Jeder Tryhard in Olympus will ihn dir jetzt abnehmen. Lass sie nicht.", ["bones"] = "Okay,\n\nDie Taverne redet immer noch über deine Würfe vom letzten Monat. Ein paar davon waren echt irre. Du bist %s, und der Glücksbringer gehört diesen Monat dir.\n\nMögen die Knochen weiter für dich fallen.", ["class"] = "Hey,\n\nIch hab nachgeschaut. Von allen, die in Olympus deine Klasse spielen, kämpft keiner wie du. Das ist riesig. Du bist jetzt %s.\n\nDie anderen werden jeden deiner Züge studieren. Lass sie. Mithalten können sie trotzdem nicht.", ["donor-month"] = "Hey,\n\nLetzten Monat hat dein Gold den Laden in Olympus am Laufen gehalten. Ehrlich, danke. Du bist %s, und der Koi gehört diesen Monat dir.\n\nBleib so großzügig.", ["donor-top"] = "Alter,\n\nDu hast mehr Gold in Olympus gesteckt als fast jeder andere. Das ist nicht wenig, das ist irre. Du bist %s, und das Füllhorn gehört dir, solange du unter den ersten drei bleibst.\n\nIch seh das, und alle anderen auch. Danke.", ["guild"] = "Hör zu,\n\nDeine Gilde hat die höchsten Stufen in ganz Olympus. Ganz oben auf der Liste. Du bist %s, und die Eule sitzt auf deinem Banner, solange deine Gilde auf Platz eins bleibt.\n\nSorg dafür, dass deine Leute weiter aufsteigen, denn die anderen kommen.", ["level"] = "Wahnsinn.\n\nDu warst in Olympus vor allen anderen da. Erster. Das kann dir keiner mehr nehmen. Der Komet gehört dir, und der Name %s auch.\n\nJetzt geh mal Gras anfassen. Oder nicht. Respekt so oder so.", ["missionary"] = "Hey,\n\nIn den letzten dreißig Tagen hast du mehr Leute in unsere Gilden gebracht als fast jeder andere. So wächst Olympus. Du bist %s, und der Hirtenstab gehört dir, solange du unter den ersten drei bleibst.\n\nBring weiter Leute rein.", ["oracle"] = "Okay,\n\nLetzten Monat hast du die Arena besser gelesen als jeder andere. Kampf für Kampf wusstest du es einfach. Du bist %s, und der Rabe gehört diesen Monat dir.\n\nJetzt kopieren alle deine Tipps. Kann man ihnen nicht verübeln.", ["race"] = "Hey,\n\nDein ganzes Volk hat gerade einen neuen Namen, mit dem es angeben kann, und es ist deiner. Du bist jetzt %s.\n\nZeig deinen Leuten, wie's geht.", ["wanted-slayer"] = "Okay,\n\nDie Horde zählt immer noch ihre Toten, und dein Name taucht ständig auf. Genau das will ich sehen. Du bist jetzt %s.\n\nReite das Skelettpferd genau dort, wo die Horde es sehen kann. Sie sollen wissen, wer das war." },
