	HONOR_TITLES = { ["apostle-1"] = "Licht von Olympus", ["apostle-2"] = "Stimme von Olympus", ["apostle-3"] = "Herold von Olympus", ["arena-champion"] = "Arena-Champion", ["arena-champion-2"] = "Arena-Anwärter", ["arena-champion-3"] = "Arena-Herausforderer", ["bones-1"] = "Meister der Knochen", ["bones-2"] = "Liebling des Glücks", ["bones-3"] = "Ruhige Hand", ["donor-month-1"] = "Goldene Hand", ["donor-month-2"] = "Silberne Hand", ["donor-month-3"] = "Bronzene Hand", ["donor-top-1"] = "Schirmherr von Olympus", ["donor-top-2"] = "Wohltäter von Olympus", ["donor-top-3"] = "Freund der Schatzkammer", ["guild-top-leader"] = "Weisester von Olympus", ["level-race-20"] = "Erster auf Stufe 20", ["level-race-40"] = "Erster auf Stufe 40", ["level-race-60"] = "Erster auf Stufe 60", ["missionary-1"] = "Guter Hirte", ["missionary-2"] = "Treuer Hirte", ["missionary-3"] = "Hirte", ["oracle-1"] = "Orakel", ["oracle-2"] = "Seher", ["oracle-3"] = "Wahrsager", ["the-dev"] = "Königlicher Entwickler", ["wanted-slayer-1"] = "Schrecken der Horde", ["wanted-slayer-2"] = "Hordenjäger", ["wanted-slayer-3"] = "Kopfgeldjäger" },
